import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  type ColorName,
  blur,
  dark,
  font,
  light,
  motion,
  radius,
  shadow,
  space,
  type,
} from './tokens.ts';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
export const outputs = {
  web: join(root, 'cloud-web', 'src', 'tokens.css'),
  mobile: join(root, 'cloud-mobile', 'src', 'lib', 'tokens.generated.ts'),
};

const banner =
  'Generated by packages/cloud-design (npm run generate). Edit src/tokens.ts there, not this file.';

/** A long value on its own lines, broken at commas within 100 columns, the way Biome formats it. */
function wrap(value: string): string {
  const lines: string[] = [];
  let line = '   ';
  for (const part of value.split(', ')) {
    const next = `${line} ${part},`;
    if (next.length > 100 && line.trim()) {
      lines.push(line);
      line = `    ${part},`;
    } else line = next;
  }
  lines.push(line);
  return lines.join('\n').slice(0, -1);
}

export function webCss(): string {
  const names = Object.keys(light) as ColorName[];
  const colors = names.map((name) => `  --${name}: light-dark(${light[name]}, ${dark[name]});`);
  return `/*
 * ${banner}
 *
 * One value per token for each scheme, written as light-dark(light, dark); tests/contrast.test.ts
 * reads this file and checks every pair that is shown together, on both schemes. Light is the
 * default (index.html sets it before the first paint).
 */
:root {
${colors.join('\n')}

  --font-sans:
${wrap(font.sans)};
  --font-mono: ${font.mono};
  --t-xs: ${type.xs}px;
  --t-sm: ${type.sm}px;
  --t-md: ${type.md}px;
  --t-lg: ${type.lg}px;
  --t-xl: ${type.xl}px;
  --t-hero: ${type.hero}px;
  --w-regular: ${type.regular};
  --w-medium: ${type.medium};

  --radius-card: ${radius.card}px;
  --radius-small: ${radius.inner}px;
  --radius-pill: ${radius.pill}px;
${Object.entries(space)
  .map(([step, px]) => `  --space-${step}: ${px}px;`)
  .join('\n')}
  --blur: ${blur};
  --ease: ${motion.ease};
  --dur-fast: ${motion.fast}ms;
  --dur: ${motion.base}ms;
}
/* light-dark() takes colors only, so the shadow follows the scheme attribute instead. */
:root,
:root[data-theme="light"] {
  color-scheme: light;
  --card-shadow: ${shadow.light};
}
:root[data-theme="dark"] {
  color-scheme: dark;
  --card-shadow: ${shadow.dark};
}
`;
}

/** React Native wants `rgba(r, g, b, a)`. */
function native(value: string): string {
  const m = /^rgb\((\d+) (\d+) (\d+) \/ ([\d.]+)\)$/u.exec(value);
  return m ? `rgba(${m[1]}, ${m[2]}, ${m[3]}, ${m[4]})` : value;
}

const camel = (name: string) => name.replace(/-([a-z])/gu, (_, c: string) => c.toUpperCase());

export function mobileTs(): string {
  const palette = (colors: typeof light) =>
    (Object.keys(colors) as ColorName[])
      .map((name) => `  ${camel(name)}: '${native(colors[name])}',`)
      .join('\n');
  return `// ${banner}

export const LIGHT_COLORS = {
${palette(light)}
} as const;

export const DARK_COLORS = {
${palette(dark)}
} satisfies Record<keyof typeof LIGHT_COLORS, string>;

export const RADIUS = { card: ${radius.card}, small: ${radius.inner}, pill: ${radius.pill} } as const;

export const TYPE = { xs: ${type.xs}, sm: ${type.sm}, md: ${type.md}, lg: ${type.lg}, xl: ${type.xl}, hero: ${type.hero} } as const;

export const WEIGHT = { regular: '${type.regular}', medium: '${type.medium}' } as const;

export const SPACE = { ${Object.entries(space)
    .map(([step, px]) => `${step}: ${px}`)
    .join(', ')} } as const;
`;
}

export function rendered(): Record<keyof typeof outputs, string> {
  return { web: webCss(), mobile: mobileTs() };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  const files = rendered();
  let stale = false;
  for (const key of Object.keys(outputs) as (keyof typeof outputs)[]) {
    const path = outputs[key];
    let current = '';
    try {
      current = readFileSync(path, 'utf8');
    } catch {
      // A missing file is stale.
    }
    if (current === files[key]) continue;
    stale = true;
    if (!check) writeFileSync(path, files[key]);
    console.log(`${check ? 'stale' : 'wrote'} ${path}`);
  }
  if (check && stale) process.exit(1);
}
